export function connectorDetails(type, operation, contract) {
 const family=families[type], recipe=recipes[`${type}/${operation}`];
 if(!recipe) return null;
 const [title,purpose,setup,input,output,limits,check]=recipe;
 const fieldHelp=field=>commonFields[field.key] || field.help || `See the ${title} procedure and the exact selected provider/function metadata for this field.`;
 const explain=items=>items.map(f=>({...f,help:fieldHelp(f)}));
 const supplemental=type==='ems'&&['send','publish'].includes(operation)
  ? [table(['Runtime setting','Meaning'],['destination','message','deliveryMode','priority','expiration','correlationId','replyTo','dynamicProperties'].map(k=>[k,commonFields[k]]))] : [];
 return {
  configuration:explain(contract.configuration),input:explain(contract.input),output:explain(contract.output),
  sections:{
   Overview:[h(title),p(purpose),h('Prerequisites'),p(family.setup)],
   Configuration:[h('Configuration procedure'),p(setup),...supplemental],
   Input:[h('Mapping example'),p('Examples are mapping/configuration assignments, not a project import file. Rename activity references using your Data tree, and replace angle-bracket placeholders with your own approved metadata. Keep credentials in properties/secrets.'),code(input)],
   Output:[h('Illustrative runtime output'),code(output),p('IDs and values are illustrative. Optional fields vary by provider response, execution mode and whether a message was received. Use the runtime shape described here when it differs from the generic editor contract.')],
   Advanced:[h('Delivery, transactions and performance'),p(family.advanced),h('Implemented behavior and limitations'),p(limits)],
   Errors:[h('Troubleshooting procedure'),p(family.errors),h('Acceptance test'),p(check)],
  },
 };
}

export function connectorFieldHelp(field) { return commonFields[field.key] || field.help; }
